  "aviation": "https://discord.com/api/webhooks/REDACTED",
  "noticias":"https://discord.com/api/webhooks/REDACTED"
};

const painelMap = {
  "latam": "https://srv1253487.hstgr.cloud/painel/api/hooks/latam/REDACTED",
  "servidores": "https://srv1253487.hstgr.cloud/painel/api/hooks/servidores/REDACTED",
