  "falhas": "https://srv1253487.hstgr.cloud/painel/api/hooks/erros_falhas/REDACTED",
  "metar": "https://srv1253487.hstgr.cloud/painel/api/hooks/metar_taf/REDACTED",
  "aviation": "https://srv1253487.hstgr.cloud/painel/api/hooks/aviation/REDACTED",
  "noticias": "https://srv1253487.hstgr.cloud/painel/api/hooks/noticias/REDACTED"
};

const DESC_MAX = 4096;

function chunksOf(text, limit) {
  const lines = String(text || '').split('\n');
  const out = [];
  let cur = '';
  const push = (s) => { if (s) out.push(s); };
  for (const line of lines) {
    if (line.length > limit) {
      push(cur);
      cur = '';
      for (let i = 0; i < line.length; i += limit) out.push(line.slice(i, i + limit));
      continue;
    }
    const next = cur ? `${cur}\n${line}` : line;
    if (next.length > limit) {
      push(cur);
      cur = line;
    } else {
      cur = next;
    }
  }
  push(cur);
  return out.length ? out : [String(text || '')];
}

function parseAi(input) {
  let aiData = input;
  if (input && input.message && typeof input.message.content === 'string') {
    try { aiData = JSON.parse(input.message.content); }
    catch (e) { aiData = { channel: 'default', payload: { embeds: [{ description: input.message.content }] } }; }
  } else if (typeof input === 'string') {
    try { aiData = JSON.parse(input); }
    catch (e) { aiData = { channel: 'default', payload: { embeds: [{ description: input }] } }; }
  }
  if (!aiData || typeof aiData !== 'object') aiData = { payload: { embeds: [] } };
  if (!aiData.payload) aiData.payload = { embeds: [] };
  if (!Array.isArray(aiData.payload.embeds)) aiData.payload.embeds = [];
  return aiData;
}

const partes = $('Partir mensagem Discord').all();
const origem = $('When Executed by Another Workflow').first().json || {};
const out = [];

$input.all().forEach((item, idx) => {
  const aiData = parseAi(item.json || {});
  const canal = String(
    partes[idx]?.json?.canal
    || aiData.channel
    || origem.canal
    || ''
  );
  const targetUrl = channelMap[canal] || channelMap[aiData.channel] || channelMap['default'];
  if (!targetUrl) throw new Error(`URL não encontrada para o canal: ${canal || aiData.channel}`);

  const base = (aiData.payload.embeds && aiData.payload.embeds[0]) || { description: String(partes[idx]?.json?.mensagem || '') };
  let pieces = chunksOf(String(base.description || ''), DESC_MAX);
  if (!pieces.length) pieces = [String(base.description || '')];
  const total = pieces.length;
  pieces.forEach((description, i) => {
    const embed = { ...base, description };
    if (embed.title && String(embed.title).length > 256) embed.title = String(embed.title).slice(0, 253) + '...';
    if (total > 1) {
      const mark = `(${i + 1}/${total})`;
      embed.title = embed.title ? `${String(embed.title).slice(0, 240)} ${mark}` : mark;
    }
    const painelUrl = painelMap[canal] || "";
    out.push({ json: { webhook_url: targetUrl, painel_url: painelUrl, payload: { embeds: [embed] } } });
  });
});

return out;

const MAX = 4096;
const LIMIT = 4000;

function chunksOf(text, limit) {
  if (text.length <= limit) return [text];
  const lines = String(text).split('\n');
  const out = [];
  let cur = '';
  const push = (s) => { if (s) out.push(s); };
  for (const line of lines) {
    if (line.length > limit) {
      push(cur);
      cur = '';
      for (let i = 0; i < line.length; i += limit) out.push(line.slice(i, i + limit));
      continue;
    }
    const next = cur ? `${cur}\n${line}` : line;
    if (next.length > limit) {
      push(cur);
      cur = line;
    } else {
      cur = next;
    }
  }
  push(cur);
  return out.length ? out : [String(text)];
}

function blocksOf(message) {
  const parts = message.split(/\n\n(?=\*[A-Z]{4}\*(?:\n|$))/);
  if (parts.length > 1) return parts;
  const paras = message.split(/\n\n/);
  return paras.length > 1 ? paras : [message];
}

function pack(message) {
  if (message.length <= MAX) return [message];
  const blocks = blocksOf(message).flatMap((b) => chunksOf(b, LIMIT));
  const packed = [];
  let cur = '';
  for (const block of blocks) {
    const sep = cur ? '\n\n' : '';
    if (cur && cur.length + sep.length + block.length > LIMIT) {
      packed.push(cur);
      cur = block;
    } else {
      cur = cur + sep + block;
    }
  }
  if (cur) packed.push(cur);
  return packed.length ? packed : [message];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const canal = j.canal;
  const mensagem = String(j.mensagem ?? '');
  const packed = pack(mensagem);
  const total = packed.length;
  packed.forEach((text, i) => {
    const body = total > 1 ? `(${i + 1}/${total})\n${text}` : text;
    out.push({ json: { canal, mensagem: body, parte: i + 1, partes: total } });
  });
}
return out;
